// Everything downstream reads these values.
// Change the query here (or add a Webhook/Email trigger in parallel).
// The threshold comes from MATCH_SCORE_THRESHOLD in .env (default 75).
return [{
  json: {
    keywords: 'developpeur python',
    limit: 15,
    threshold: Number($env.MATCH_SCORE_THRESHOLD || 75)
  }
}];

const query = $('Build Search Query').first().json;
const payload = $input.first().json;

if (payload.status === 'error') {
  throw new Error('Scraper error: ' + payload.message);
}

const jobs = payload.jobs || [];
if (jobs.length === 0) {
  throw new Error('Scraper returned no jobs for: ' + query.keywords);
}

// One output item per job, carrying the original query + threshold
return jobs.map((job) => ({
  json: { ...job, keywords: query.keywords, threshold: query.threshold }
}));

// Flattens the ai-service response into one stable shape for the IF,
// Telegram and Google Sheets nodes: match_score / match_rationale / missing_skills
return $input.all().map((item) => {
  const body = item.json;
  const job = $('Extract Jobs').item.json; // keeps pairing with the source job

  if (body.status === 'error') {
    return {
      json: {
        ...job,
        match_score: 0,
        verdict: 'skip',
        matched_skills: [],
        missing_skills: [],
        match_rationale: 'Scoring failed: ' + body.message,
        model: null,
        checked_at: new Date().toISOString()
      }
    };
  }

  const result = body.result || {};
  return {
    json: {
      title: job.title,
      company: job.company,
      location: job.location,
      link: job.link,
      source: job.source,
      keywords: job.keywords,
      threshold: job.threshold,
      match_score: result.score,
      verdict: result.verdict,
      matched_skills: result.matched_skills || [],
      missing_skills: result.missing_skills || [],
      match_rationale: result.rationale,
      model: result.model,
      checked_at: new Date().toISOString()
    }
  };
});

// Builds one rich MarkdownV2 alert per passing job. Dynamic values are
// escaped because Telegram's MarkdownV2 rejects unescaped
// _ * [ ] ( ) ~ ` > # + - = | { } . !
// Note: inside Code nodes use $input/$(), NOT $json (that shortcut is expressions-only).
const esc = (v) => String(v ?? '').replace(/([_*\[\]()~`>#+\-=|{}.!\\])/g, '\\$1');

return $input.all().map((item) => {
  const j = item.json;
  const missing = Array.isArray(j.missing_skills) && j.missing_skills.length
    ? j.missing_skills.map(esc).join(', ')
    : 'None flagged';

  const text = [
    `🎯 *Match Score:* ${esc(j.match_score)}/100`,
    `💼 *Title:* ${esc(j.title)}`,
    `🏢 *Company:* ${esc(j.company || 'n/a')}`,
    `📍 *Location:* ${esc(j.location || 'n/a')}`,
    `🔗 *Apply Link:* ${esc(j.link)}`,
    `💡 *Key Match Rationale:* ${esc(j.match_rationale || 'n/a')}`,
    `⚠️ *Missing Skills / Gaps:* ${missing}`
  ].join('\n');

  return { json: { ...j, telegram_text: text } };
});
